using System;using System.Drawing;class ZonesTest{[STAThread]static void Main(){using(var chart=new Chart())using(var b=new Bitmap(1100,1050)){chart.Size=b.Size;var d=new Device("Test"){HostStatus="inaktiv"};var i=new Inventory();i.Devices.Add(d);chart.SetData(i);d.Pos=new PointF(520,520);chart.DrawToBitmap(b,chart.ClientRectangle);if(b.GetPixel(725,520).R!=255)throw new Exception("idle");chart.SelectDevice(d);chart.DrawToBitmap(b,chart.ClientRectangle);var green=b.GetPixel(765,520);var yellow=b.GetPixel(780,520);var red=b.GetPixel(800,520);if(green.G<=green.R||yellow.B>=yellow.G||red.R<=red.G||b.GetPixel(532,520).ToArgb()!=Color.Silver.ToArgb())throw new Exception("zones or icon");Console.WriteLine("OK");}}}